E
cat > Api.Tests/PayByCardSteps.cs <<'E'
using Reqnroll;
using Xunit;

namespace Api.Tests;

[Binding]
public class PayByCardSteps
{
    private readonly Payments _payments = new();
    private PaymentResult? _result;

    [Given("a returning customer with a valid card")]
    public void GivenAReturningCustomerWithAValidCard() { }

    [When("a basket of {int} cents is paid")]
    public void WhenABasketIsPaid(int cents) => _result = _payments.PayByCard(cents);

    [Then("the payment is accepted for {int} cents")]
    public void ThenThePaymentIsAccepted(int cents)
    {
        Assert.NotNull(_result);
        Assert.True(_result.Accepted);
        Assert.Equal(cents, _result.AmountCents);
    }
}
E
cat > Api.slnx <<'E'
<Solution>
  <Project Path="Api/Api.csproj" />
  <Project Path="Api.Tests/Api.Tests.csproj" />
</Solution>
E
dotnet build Api.slnx --nologo 2>&1 | tail -8 && dotnet test Api.slnx --nologo --no-build 2>&1 | tail -6
cd ../Batch && printf '\n[tool.pytest.ini_options]\npythonpath = ["."]\ntestpaths = ["tests"]\n' >> pyproject.toml
(pip install -q pytest ruff 2>&1|tail -1); ruff check . && pytest -q

